def _z(*runs):
    """a wave's sixteen zones from (raw wave, count) runs and single raw waves"""
    out = []
    for r in runs:
        out += [r[0]] * r[1] if isinstance(r, tuple) else [r]
    assert len(out) == 16, runs
    return out


