DOC_CLOCK = 8_000_000
DOC_OSCS = 24
FS = DOC_CLOCK / 8 / (DOC_OSCS + 2)                 # 38461.5 Hz: the DOC's scan rate with 24 oscillators


def raw_size(i):
    return 256 << ((RAW[i][1] >> 3) & 7)


def raw_res(i):
    return RAW[i][1] & 7


def raw_cycles(i):
    """cycles of the played note in the table: a resolution-1 table is one cycle (f = FS * FR / 2^(17 + res))"""
    return 1 << (raw_res(i) - 1)
